class GameObject {
    float x = 0, y = 0;                        // pan-domain state
    std::unique_ptr<InputComponent>    input;   // pluggable slots
    std::unique_ptr<PhysicsComponent>  physics;
    std::unique_ptr<GraphicsComponent> graphics;
public:
    void update(float dt) {
        if (input)    input->update(*this);
        if (physics)  physics->update(*this, dt);
        if (graphics) graphics->draw(*this);
    }
};

